<?php
namespace App\Http\Controllers;
use App\Models\Customer; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class CustomerController extends Controller { public function index(Request $request) { $customers = Customer::query()->when($request->string('search')->toString(), fn ($query, $search) => $query->where('name','like',"%{$search}%")->orWhere('rfc','like',"%{$search}%"))->orderBy('name')->get(); return view('customers.index', compact('customers')); } public function store(Request $request) { Customer::create($this->data($request)); return redirect()->route('customers.index'); } public function update(Request $request, Customer $customer) { $customer->update($this->data($request, $customer)); return redirect()->route('customers.index'); } private function data(Request $request, ?Customer $customer = null): array { return $request->validate(['type'=>['required','in:fisica,moral'],'name'=>['required','string','max:255'],'rfc'=>['required','string','max:13',Rule::unique('customers')->ignore($customer)],'email'=>['required','email'],'phone'=>['required','string','max:30'],'address'=>['required','string','max:255'],'postal_code'=>['required','string','max:10']]); } }
